  $imcojson${"slug": "introduction-to-mass-communication", "title": "Introduction to Mass Communication", "description": "A survey of media systems, journalism, platforms, audiences, industries, law, ethics, representation, and public life.", "topics": [{"id": "936c1e4e-c8a9-46d9-b478-133c0bdb260e", "type": "topic", "title": "History of Mass Media", "description": "Students trace how communication technologies, institutions, audiences, and public life developed from print culture to networked digital media.", "children": [{"id": "874704b5-0f95-4e48-86a5-ac978b536135", "type": "subtopic", "title": "The rise of print culture", "children": [{"id": "a6d0c25b-18ef-4730-98f7-d64fa5da3130", "type": "concept", "title": "printing press"}, {"id": "ef676cf5-4038-434e-9e7d-fbf329a6118c", "type": "concept", "title": "newspapers and magazines"}, {"id": "8ee0a046-7cf3-4908-910e-ecec261955af", "type": "concept", "title": "public sphere"}], "description": "Students learn how printing, literacy, newspapers, and pamphlets expanded public debate and commercial media."}, {"id": "1e05905b-2f97-412a-9cab-b5dd9dc343bd", "type": "subtopic", "title": "Telegraph, photography, and industrial news", "children": [{"id": "29eae308-e4b3-45b5-8583-c2a3b1004f41", "type": "concept", "title": "wire services"}, {"id": "ed27141e-bb1b-462b-8029-26815f1b80f1", "type": "concept", "title": "photojournalism"}, {"id": "65eb0c66-5b0a-4257-8930-a8a352ace6fa", "type": "concept", "title": "mass circulation press"}], "description": "The unit shows how speed, images, wires, and mass production changed what counted as news."}, {"id": "c88baa46-ae65-468e-aff2-c167cb39a7b7", "type": "subtopic", "title": "Broadcasting and national audiences", "children": [{"id": "35b0031b-814d-491c-b0c4-28a4f9264334", "type": "concept", "title": "radio networks"}, {"id": "ddf64189-b9c8-4113-b71a-ff3bffdb5121", "type": "concept", "title": "television news"}, {"id": "226417f4-bbc6-46e2-9a4e-755e223e42b7", "type": "concept", "title": "broadcast regulation"}], "description": "Students examine radio and television as technologies that created shared public events and powerful regulatory debates."}, {"id": "7a8b20f8-0bcb-4a30-91b1-ecc54c3f511e", "type": "subtopic", "title": "Digital convergence", "children": [{"id": "47bb8fa3-469d-4236-bd36-47d84f006fb1", "type": "concept", "title": "internet history"}, {"id": "e2fbed82-647d-4a02-885c-9eb254c17807", "type": "concept", "title": "mobile media"}, {"id": "09fafbb1-3389-4f6c-8595-8fc87234f710", "type": "concept", "title": "platform convergence"}], "description": "The class connects computing, the web, mobile devices, and social platforms to changes in production and consumption."}]}, {"id": "5259c954-027c-40c3-970a-78ee788fc150", "type": "topic", "title": "Media Theories and Research Traditions", "description": "This section gives students a vocabulary for analyzing how media messages are produced, interpreted, circulated, and contested.", "children": [{"id": "03b458e5-baa4-400d-9174-3237e7983174", "type": "subtopic", "title": "Transmission and ritual views of communication", "children": [{"id": "bd8d4790-415e-4c87-b7ac-16e47fc094b4", "type": "concept", "title": "sender-message-receiver models"}, {"id": "0151149c-992e-405b-aa6a-8cdc320ba1dd", "type": "concept", "title": "ritual communication"}, {"id": "4491cdd0-5263-4144-a705-19ad74640158", "type": "concept", "title": "symbolic interaction"}], "description": "Students compare communication as information transfer with communication as shared culture and meaning-making."}, {"id": "6e81ad21-9912-452e-a02d-c6bd61bbfe32", "type": "subtopic", "title": "Agenda-setting, framing, and gatekeeping", "children": [{"id": "588fc355-b804-4dc2-a6b3-9f51a39afcab", "type": "concept", "title": "issue salience"}, {"id": "491bbe27-4101-4e32-b174-4f762239bfc7", "type": "concept", "title": "frames"}, {"id": "f9b1d2df-16be-4ed7-9404-70a3f8095a71", "type": "concept", "title": "editorial gates"}], "description": "The course shows how media can shape public attention without simply telling people what to think."}, {"id": "30bdd030-e45b-4cbb-ac3e-003fac102d9d", "type": "subtopic", "title": "Uses and gratifications", "children": [{"id": "71f1b1a2-a7d7-42f6-9607-6dd14bb8406d", "type": "concept", "title": "information"}, {"id": "79fba7c1-05a9-4f76-bdcf-227bbfb9f462", "type": "concept", "title": "identity"}, {"id": "a0b88e66-b116-4fed-b7ce-3ce285b50009", "type": "concept", "title": "entertainment and social connection"}], "description": "Students learn to ask what audiences actively seek from media rather than treating audiences as passive recipients."}, {"id": "ea28ea81-eb74-468d-ab8c-88ba46d8bdc3", "type": "subtopic", "title": "Critical and cultural theories", "children": [{"id": "4f2a97bc-7099-4173-85df-9773b6b8ab57", "type": "concept", "title": "hegemony"}, {"id": "677c24ff-8b77-4df8-a39d-fb95eb51c8cd", "type": "concept", "title": "encoding/decoding"}, {"id": "9e84f3fd-b886-41dc-852d-d8ef57722a87", "type": "concept", "title": "political economy"}], "description": "Students examine power, ideology, representation, political economy, and cultural production."}]}, {"id": "6ff7d23b-2603-4b70-a0b7-f7f28d10118c", "type": "topic", "title": "Print Media and News Institutions", "description": "Students learn why print and text-based news still matter: they shaped professional norms, public records, investigative methods, and civic accountability.", "children": [{"id": "afafdbf0-5575-437d-bf30-ee5ffdece9f9", "type": "subtopic", "title": "Newspapers and magazines", "children": [{"id": "2931da70-628e-4500-a505-32d52549d1c1", "type": "concept", "title": "beat reporting"}, {"id": "4e302cf6-6cdb-4a31-8059-f9c39ad0c4ad", "type": "concept", "title": "editorial workflow"}, {"id": "1d43cfdd-6b24-4f1d-8a7e-3da5065d9e26", "type": "concept", "title": "magazine genres"}], "description": "The class studies story forms, beats, editorial hierarchies, and the business history of print journalism."}, {"id": "22ae5990-e020