"}, {"id": "0d0cddf8-fc5d-45ef-aae9-0849bd13c63d", "type": "concept", "title": "AI-assisted production"}, {"id": "9697875e-ceb2-49a8-aa1e-d5a8b03f17a0", "type": "concept", "title": "disclosure norms"}], "description": "The course introduces generative AI, deepfakes, disclosure ethics, and verification challenges."}]}, {"id": "f7b97341-5f68-49f3-b77c-6758f86941ef", "type": "topic", "title": "Advertising, Public Relations, and Strategic Communication", "description": "This section helps students distinguish journalism from persuasive communication while understanding how advertising and PR fund, influence, and compete with news.", "children": [{"id": "170e5bbd-7a00-42ec-a80c-19d56a7196d9", "type": "subtopic", "title": "Advertising models", "children": [{"id": "95a2c199-e76e-45a2-bfb6-153d54d45fa0", "type": "concept", "title": "display ads"}, {"id": "f6bf01bc-8678-4d46-9532-603a37b41e2f", "type": "concept", "title": "programmatic advertising"}, {"id": "aff3e493-8482-4dd0-b5c4-21af9fad46b9", "type": "concept", "title": "native advertising"}], "description": "Students learn how advertising evolved from print display to targeting, programmatic markets, sponsorship, and influencer marketing."}, {"id": "c8086775-c7d4-47d0-a8b8-2edd26d7cc1e", "type": "subtopic", "title": "Public relations and institutional messaging", "children": [{"id": "d3c22fcf-545d-4533-89ad-d200818b01d1", "type": "concept", "title": "press releases"}, {"id": "3c74ea94-ebe9-4f2f-8c69-f5dafcb031b2", "type": "concept", "title": "spokespeople"}, {"id": "ce592faa-6afd-418d-ac48-4a18113820bf", "type": "concept", "title": "crisis messaging"}], "description": "The course examines press releases, media relations, crisis communication, and source access."}, {"id": "9c6fd336-7985-4609-9355-d5512eed99d5", "type": "subtopic", "title": "Persuasion and branding", "children": [{"id": "c2cbf10c-024b-4620-8188-1d6abbd2ab9d", "type": "concept", "title": "brand positioning"}, {"id": "a4d2838e-ac7c-4958-bc7b-fcb096a85fe0", 