  data = $imcojson${"slug": "introduction-to-mass-communication", "title": "Introduction to Mass Communication", "description": "A survey of media systems, journalism, platforms, audiences, industries, law, ethics, representation, and public life.", "topics": [{"id": "936c1e4e-c8a9-46d9-b478-133c0bdb260e", "type": "topic", "title": "History of Mass Media", "description": "Students trace how communication technologies, institutions, audiences, and public life developed from print culture to networked digital media.", "children": [{"id": "874704b5-0f95-4e48-86a5-ac978b536135", "type": "subtopic", "title": "The rise of print culture", "children": [{"id": "a6d0c25b-18ef-4730-98f7-d64fa5da3130", "type": "concept", "title": "printing press"}, {"id": "ef676cf5-4038-434e-9e7d-fbf329a6118c", "type": "concept", "title": "newspapers and magazines"}, {"id": "8ee0a046-7cf3-4908-910e-ecec261955af", "type": "concept", "title": "public sphere"}], "description": "Students learn how printing, literacy, newspapers, and pamphlets expanded public debate and commercial media."}, {"id": "1e05905b-2f97-412a-9cab-b5dd9dc343bd", "type": "subtopic", "title": "Telegraph, photography, and industrial news", "children": [{"id": "29eae308-e4b3-45b5-8583-c2a3b1004f41", "type": "concept", "title": "wire services"}, {"id": "ed27141e-bb1b-462b-8029-26815f1b80f1", "type": "concept", "title": "photojournalism"}, {"id": "65eb0c66-5b0a-4257-8930-a8a352ace6fa", "type": "concept", "title": "mass circulation press"}], "description": "The unit shows how speed, images, wires, and mass production changed what counted as news."}, {"id": "c88baa46-ae65-468e-aff2-c167cb39a7b7", "type": "subtopic", "title": "Broadcasting and national audiences", "children": [{"id": "35b0031b-814d-491c-b0c4-28a4f9264334", "type": "concept", "title": "radio networks"}, {"id": "ddf64189-b9c8-4113-b71a-ff3bffdb5121", "type": "concept", "title": "television news"}, {"id": "226417f4-bbc6-46e2-9a4e-755e223e42b7", "type": "concept", "title": "broadcast regulation"}], "description": "Students examine radio and television as technologies that created shared public events and powerful regulatory debates."}, {"id": "7a8b20f8-0bcb-4a30-91b1-ecc54c3f511e", "type": "subtopic", "title": "Digital convergence", "children": [{"id": "47bb8fa3-469d-4236-bd36-47d84f006fb1", "type": "concept", "title": "internet history"}, {"id": "e2fbed82-647d-4a02-885c-9eb254c17807", "type": "concept", "title": "mobile media"}, {"id": "09fafbb1-3389-4f6c-8595-8fc87234f710", "type": "concept", "title": "platform convergence"}], "description": "The class connects computing, the web, mobile devices, and social platforms to changes in production and consumption."}]}, {"id": "5259c954-027c-40c3-970a-78ee788fc150", "type": "topic", "title": "Media Theories and Research Traditions", "description": "This section gives students a vocabulary for analyzing how media messages are produced, interpreted, circulated, and contested.", "children": [{"id": "03b458e5-baa4-400d-9174-3237e7983174", "type": "subtopic", "title": "Transmission and ritual views of communication", "children": [{"id": "bd8d4790-415e-4c87-b7ac-16e47fc094b4", "type": "concept", "title": "sender-message-receiver models"}, {"id": "0151149c-992e-405b-aa6a-8cdc320ba1dd", "type": "concept", "title": "ritual communication"}, {"id": "4491cdd0-5263-4144-a705-19ad74640158", "type": "concept", "title": "symbolic interaction"}], "description": "Students compare communication as information transfer with communication as shared culture and meaning-making."}, {"id": "6e81ad21-9912-452e-a02d-c6bd61bbfe32", "type": "subtopic", "title": "Agenda-setting, framing, and gatekeeping", "children": [{"id": "588fc355-b804-4dc2-a6b3-9f51a39afcab", "type": "concept", "title": "issue salience"}, {"id": "491bbe27-4101-4e32-b174-4f762239bfc7", "type": "concept", "title": "frames"}, {"id": "f9b1d2df-16be-4ed7-9404-70a3f8095a71", "type": "concept", "title": "editorial gates"}], "description": "The course shows how media can shape public attention without simply telling people what to think."}, {"id": "30bdd030-e45b-4cbb-ac3e-003fac102d9d", "type": "subtopic", "title": "Uses and gratifications", "children": [{"id": "71f1b1a2-a7d7-42f6-9607-6dd14bb8406d", "type": "concept", "title": "information"}, {"id": "79fba7c1-05a9-4f76-bdcf-227bbfb9f462", "type": "concept", "title": "identity"}, {"id": "a0b88e66-b116-4fed-b7ce-3ce285b50009", "type": "concept", "title": "entertainment and social connection"}], "description": "Students learn to ask what audiences actively seek from media rather than treating audiences as passive recipients."}, {"id": "ea28ea81-eb74-468d-ab8c-88ba46d8bdc3", "type": "subtopic", "title": "Critical and cultural theories", "children": [{"id": "4f2a97bc-7099-4173-85df-9773b6b8ab57", "type": "concept", "title": "hegemony"}, {"id": "677c24ff-8b77-4df8-a39d-fb95eb51c8cd", "type": "concept", "title": "encoding/decoding"}, {"id": "9e84f3fd-b886-41dc-852d-d8ef57722a87", "type": "concept", "title": "political economy"}], "description": "Students examine power, ideology, representation, political economy, and cultural production."}]}, {"id": "6ff7d23b-2603-4b70-a0b7-f7f28d10118c", "type": "topic", "title": "Print Media and News Institutions", "description": "Students learn why print and text-based news still matter: they shaped professional norms, public records, investigative methods, and civic accountability.", "children": [{"id": "afafdbf0-5575-437d-bf30-ee5ffdece9f9", "type": "subtopic", "title": "Newspapers and magazines", "children": [{"id": "2931da70-628e-4500-a505-32d52549d1c1", "type": "concept", "title": "beat reporting"}, {"id": "4e302cf6-6cdb-4a31-8059-f9c39ad0c4ad", "type": "concept", "title": "editorial workflow"}, {"id": "1d43cfdd-6b24-4f1d-8a7e-3da5065d9e26", "type": "concept", "title": "magazine genres"}], "description": "The class studies story forms, beats, editorial hierarchies, and the business history of print journalism."}, {"id": "22ae5990-e020-4cc5-a612-64d55f3a15eb", "type": "subtopic", "title": "News values and professional routines", "children": [{"id": "5ba36fc7-7526-47fb-9be7-dbfb3f91e0cb", "type": "concept", "title": "timeliness"}, {"id": "be6cc94a-d63c-4272-8b70-9cf65d29036b", "type": "concept", "title": "proximity and impact"}, {"id": "c0c480b3-d99f-427a-95da-555b7c5e8c43", "type": "concept", "title": "routines and deadlines"}], "description": "Students identify the criteria and routines that determine what becomes news."}, {"id": "142ea5c6-ba68-433c-951d-baa2ea53381a", "type": "subtopic", "title": "Investigative and public-service traditions", "children": [{"id": "0b005c5d-4ceb-4066-866b-a382c998b8ce", "type": "concept", "title": "muckraking"}, {"id": "1e6d2cc0-3037-4bbf-954a-32cc05a14555", "type": "concept", "title": "documents"}, {"id": "33c44ea0-b57f-4619-8492-eb88d4b84a3b", "type": "concept", "title": "public-interest journalism"}], "description": "Students connect print institutions to watchdog reporting, records work, and long-form accountability journalism."}, {"id": "1af18196-a06f-4f0e-9fc2-b8d57340ae4d", "type": "subtopic", "title": "Print in the digital era", "children": [{"id": "49fcd148-945d-4c1a-83ba-9db3fe29ae00", "type": "concept", "title": "paywalls"}, {"id": "9e8162b8-9cb0-45d0-9b23-054a2af2a36e", "type": "concept", "title": "newsletters"}, {"id": "89c7d523-a53d-4313-a81e-0cf640c485bf", "type": "concept", "title": "audience revenue"}], "description": "The unit examines how legacy organizations adapted to subscriptions, newsletters, podcasts, and digital editions."}]}, {"id": "955c011c-3358-45f8-86f1-cdde8afbc646", "type": "topic", "title": "Broadcast, Audio, and Video Media", "description": "This unit introduces media that reach audiences through sound and moving image, with attention to immediacy, performance, production, and regulation.", "children": [{"id": "bbb1e0ac-ad2b-4aa0-b499-52d92f8ce09c", "type": "subtopic", "title": "Radio and podcasting", "children": [{"id": "9f5e695f-b91e-4647-96c6-92d84bc2419b", "type": "concept", "title": "radio news"}, {"id": "ec497a62-78dc-47f3-865d-71898a9f130a", "type": "concept", "title": "podcast formats"}, {"id": "5b52d5e8-0ef8-48a4-9e2f-52e30470a8fe", "type": "concept", "title": "audio storytelling"}], "description": "Students learn how audio creates intimacy, rhythm, voice, and low-barrier distribution."}, {"id": "a12eaebf-fdce-4335-a84b-b880fc67e011", "type": "subtopic", "title": "Television news and visual authority", "children": [{"id": "191cc3d7-aed7-47f3-900f-141b1b1a446a", "type": "concept", "title": "visual evidence"}, {"id": "5f31c629-bddb-4af0-bc2a-07c333329f08", "type": "concept", "title": "live reporting"}, {"id": "1b393186-e39f-40b4-95b2-dcf54ffb6c16", "type": "concept", "title": "broadcast writing"}], "description": "The course examines how images, anchors, live shots, and production choices shape credibility and emotion."}, {"id": "5ed12cb9-d989-420a-ad0c-509ecc60477b", "type": "subtopic", "title": "Documentary and nonfiction video", "children": [{"id": "74a40b03-a31d-4063-833a-9b12cb8d8320", "type": "concept", "title": "documentary modes"}, {"id": "bcfec5fa-2706-4bba-affb-56d227c5176d", "type": "concept", "title": "interviews"}, {"id": "f335993f-50a3-41ad-a188-91be50a93ed1", "type": "concept", "title": "sequence and scene"}], "description": "Students consider how longer visual forms combine reporting, narrative, ethics, and editing."}, {"id": "c4a29f6f-b8c0-4b40-9300-63b7fcaf3e19", "type": "subtopic", "title": "Streaming and platform video", "children": [{"id": "8571f954-a3f6-4cad-8c2f-2b9bbc591e9b", "type": "concept", "title": "creator economy"}, {"id": "76d359b6-557d-4b4a-ab80-0a5b8c3f0997", "type": "concept", "title": "short-form platforms"}, {"id": "539dd638-454d-4217-a810-552eaf941ff0", "type": "concept", "title": "on-demand viewing"}], "description": "The unit covers YouTube, short-form video, streaming services, and shifting audience habits."}]}, {"id": "a410e190-62b4-4f65-b865-74e053d716e5", "type": "topic", "title": "Digital, Social, and Platform Media", "description": "Students learn how platforms reorganize media production, distribution, audience behavior, power, and public discourse.", "children": [{"id": "ef181213-bad9-4102-9a8e-6f310416697e", "type": "subtopic", "title": "Web-native journalism", "children": [{"id": "b3fb62eb-03ba-4a48-af22-fb3677e8e30d", "type": "concept", "title": "SEO"}, {"id": "318251cd-d93a-4559-b695-032092d1cc1e", "type": "concept", "title": "live blogs"}, {"id": "98bf8919-fdcc-49b8-95c1-ea271b2293ca", "type": "concept", "title": "interactive storytelling"}], "description": "The class covers linking, search, multimedia, newsletters, live coverage, and updating stories over time."}, {"id": "f9594277-5e28-41e9-8846-ba17c12f7a07", "type": "subtopic", "title": "Social media as infrastructure", "children": [{"id": "6dadf4b7-12f6-45ec-afe6-288b9ab711da", "type": "concept", "title": "feeds"}, {"id": "09be0a5c-4db2-48b8-8335-d41369fc654c", "type": "concept", "title": "recommendation systems"}, {"id": "2c25cdb6-c97a-4246-8184-45001a0e1d31", "type": "concept", "title": "content moderation"}], "description": "Students examine platforms as publishing systems, discovery engines, conversation spaces, and moderation regimes."}, {"id": "29895079-afb7-4830-9f5b-871ac5a0310e", "type": "subtopic", "title": "Audience analytics", "children": [{"id": "74330478-8e5e-4b6d-a686-2652199be174", "type": "concept", "title": "pageviews"}, {"id": "6b69eb26-ffaa-41f7-ad8b-669610f114d1", "type": "concept", "title": "engagement"}, {"id": "329fdb56-b743-4712-9539-8f7179be89a1", "type": "concept", "title": "conversion and retention"}], "description": "Students learn how metrics influence editorial judgment and where metrics can mislead."}, {"id": "218f3295-efff-48dd-bfe1-c1f48df473b7", "type": "subtopic", "title": "AI and synthetic media", "children": [{"id": "6f80be29-c356-4940-ba6e-9e8364fe4450", "type": "concept", "title": "synthetic images"}, {"id": "0d0cddf8-fc5d-45ef-aae9-0849bd13c63d", "type": "concept", "title": "AI-assisted production"}, {"id": "9697875e-ceb2-49a8-aa1e-d5a8b03f17a0", "type": "concept", "title": "disclosure norms"}], "description": "The course introduces generative AI, deepfakes, disclosure ethics, and verification challenges."}]}, {"id": "f7b97341-5f68-49f3-b77c-6758f86941ef", "type": "topic", "title": "Advertising, Public Relations, and Strategic Communication", "description": "This section helps students distinguish journalism from persuasive communication while understanding how advertising and PR fund, influence, and compete with news.", "children": [{"id": "170e5bbd-7a00-42ec-a80c-19d56a7196d9", "type": "subtopic", "title": "Advertising models", "children": [{"id": "95a2c199-e76e-45a2-bfb6-153d54d45fa0", "type": "concept", "title": "display ads"}, {"id": "f6bf01bc-8678-4d46-9532-603a37b41e2f", "type": "concept", "title": "programmatic advertising"}, {"id": "aff3e493-8482-4dd0-b5c4-21af9fad46b9", "type": "concept", "title": "native advertising"}], "description": "Students learn how advertising evolved from print display to targeting, programmatic markets, sponsorship, and influencer marketing."}, {"id": "c8086775-c7d4-47d0-a8b8-2edd26d7cc1e", "type": "subtopic", "title": "Public relations and institutional messaging", "children": [{"id": "d3c22fcf-545d-4533-89ad-d200818b01d1", "type": "concept", "title": "press releases"}, {"id": "3c74ea94-ebe9-4f2f-8c69-f5dafcb031b2", "type": "concept", "title": "spokespeople"}, {"id": "ce592faa-6afd-418d-ac48-4a18113820bf", "type": "concept", "title": "crisis messaging"}], "description": "The course examines press releases, media relations, crisis communication, and source access."}, {"id": "9c6fd336-7985-4609-9355-d5512eed99d5", "type": "subtopic", "title": "Persuasion and branding", "children": [{"id": "c2cbf10c-024b-4620-8188-1d6abbd2ab9d", "type": "concept", "title": "brand positioning"}, {"id": "a4d2838e-ac7c-4958-bc7b-fcb096a85fe0", "type": "concept", "title": "campaign strategy"}, {"id": "2af3c4cd-cc0e-42b0-a457-fbf6d1bb3dcf", "type": "concept", "title": "target audiences"}], "description": "Students analyze how campaigns use emotion, identity, repetition, and social proof."}, {"id": "b20a2a16-d460-41cf-95dc-39a5d2d190f1", "type": "subtopic", "title": "Ethical boundaries", "children": [{"id": "bc4a44be-0b80-4a85-a89d-4c23d821cd4a", "type": "concept", "title": "advertorials"}, {"id": "0f03c778-760f-417c-afe5-59c46a2bc0f4", "type": "concept", "title": "influencer disclosure"}, {"id": "3909e63c-294b-42f9-b78e-e889474bf6c8", "type": "concept", "title": "church-state separation"}], "description": "Students learn to identify conflicts, sponsored content, undisclosed influence, and blurred editorial lines."}]}, {"id": "ccf5c751-8512-43a1-86ab-18c7f328ac82", "type": "topic", "title": "Media Economics, Ownership, and Business Models", "description": "Students learn that media content is shaped by economic structures: ownership, labor, technology, advertising, subscriptions, and platform dependency.", "children": [{"id": "6e322300-f821-4a04-869a-efe93b5dbf25", "type": "subtopic", "title": "Ownership and concentration", "children": [{"id": "f357c102-3515-45dc-80a2-0948f7634c4b", "type": "concept", "title": "media conglomerates"}, {"id": "91ab3be2-3858-41a2-b89a-de90fa102b88", "type": "concept", "title": "local news deserts"}, {"id": "2cc095ac-ded9-4f03-b48f-4852cf3bea9b", "type": "concept", "title": "public and nonprofit media"}], "description": "The class examines conglomerates, local news consolidation, hedge-fund ownership, public media, and nonprofit models."}, {"id": "92cf81c8-5a99-45c0-b803-28c372e45e66", "type": "subtopic", "title": "Revenue models", "children": [{"id": "cbef8a29-3d9b-413c-9deb-11c470925bcd", "type": "concept", "title": "audience revenue"}, {"id": "98597595-ad45-4166-9922-4fc4f0be1116", "type": "concept", "title": "philanthropy"}, {"id": "71c4b744-94c1-4a79-a143-933a72e9f064", "type": "concept", "title": "events and sponsorships"}], "description": "Students compare advertising, subscriptions, membership, philanthropy, licensing, events, and platform revenue."}, {"id": "ee13df21-31a5-4e93-aeae-491877819291", "type": "subtopic", "title": "Platform economics", "children": [{"id": "753e2d4e-5eb5-44d6-a4c3-c8e4b77f0aa4", "type": "concept", "title": "platform dependency"}, {"id": "29fa13be-e164-4138-a666-f5cfcde26e2d", "type": "concept", "title": "algorithmic distribution"}, {"id": "1658070d-73da-44c4-ba20-daeca03a4ead", "type": "concept", "title": "creator monetization"}], "description": "Students learn how search engines, social networks, app stores, and video platforms affect traffic and bargaining power."}, {"id": "3b031bda-4c8c-41bc-93ce-87f22fa746d1", "type": "subtopic", "title": "Labor and newsroom change", "children": [{"id": "a2976563-5895-4d8f-bc72-82305e918dc8", "type": "concept", "title": "newsroom jobs"}, {"id": "b82c96b1-a6d8-44cc-bfb5-d5dfd76430d1", "type": "concept", "title": "freelancing"}, {"id": "952a8620-bb0c-46db-b9f7-741713f408ae", "type": "concept", "title": "automation and workflow"}], "description": "The unit covers newsroom roles, freelance work, unions, automation, and changing career pathways."}]}, {"id": "5b30c815-9156-4037-84ed-e969ff5775dd", "type": "topic", "title": "Media Effects, Audiences, and Public Opinion", "description": "This unit introduces evidence-based ways to discuss influence without overstating media power or ignoring audience agency.", "children": [{"id": "71e26c60-9cfd-4321-86c9-250eea89a36a", "type": "subtopic", "title": "Effects research basics", "children": [{"id": "49eb9e16-5455-4890-af72-370943a372c6", "type": "concept", "title": "experiments"}, {"id": "18781e24-5706-4b51-8628-da3f6c603a3b", "type": "concept", "title": "surveys"}, {"id": "de6c49c6-5571-4ef1-ac9b-1a2b53e314f3", "type": "concept", "title": "longitudinal research"}], "description": "Students learn the difference between correlation, causation, short-term effects, and long-term social influence."}, {"id": "b2c0e570-9287-4d11-b413-4067ff01ca34", "type": "subtopic", "title": "Public opinion and political communication", "children": [{"id": "c8647170-7a26-416f-be58-6384e2c609e2", "type": "concept", "title": "opinion formation"}, {"id": "cbc00652-e4bc-4ce0-87b5-d7378868955b", "type": "concept", "title": "political ads"}, {"id": "ec905a5d-5271-4cb4-806f-e9f8bc1d4211", "type": "concept", "title": "polarization"}], "description": "The class studies campaigns, polarization, agenda-setting, framing, and media trust."}, {"id": "17e26891-834c-4b51-b75c-09c5dd48f3b9", "type": "subtopic", "title": "Media psychology and identity", "children": [{"id": "c4c864b6-be83-4de2-bef5-5fc6c734363d", "type": "concept", "title": "parasocial relationships"}, {"id": "14eccb4f-3406-4890-8126-447aee48b866", "type": "concept", "title": "identity formation"}, {"id": "8fd0ef2a-4a96-4a49-9939-64ded9ff7ad5", "type": "concept", "title": "mood management"}], "description": "Students examine how people use media for belonging, emotion, identity, and self-presentation."}, {"id": "cbd8aca0-462c-4de1-91f3-ec14f5ca01a5", "type": "subtopic", "title": "Children, vulnerable audiences, and media literacy", "children": [{"id": "4e6fbe95-e543-44e8-9e94-f0e522d2dd9d", "type": "concept", "title": "children and media"}, {"id": "fcc411c0-9486-44c9-8987-8762be8a7054", "type": "concept", "title": "media literacy"}, {"id": "e29684d9-8890-4eca-8127-19205ca5dfd7", "type": "concept", "title": "civic education"}], "description": "Students consider developmental, educational, and civic approaches to media effects."}]}, {"id": "6316fbd9-7755-4d0b-8252-c553a83b10cb", "type": "topic", "title": "Media Law, Ethics, and Press Freedom", "description": "Students gain a first-year map of the legal and ethical standards that shape responsible journalism and communication work.", "children": [{"id": "b67fe8c9-89e1-4f99-9aab-84f33d65f2ba", "type": "subtopic", "title": "First Amendment and press freedom", "children": [{"id": "da669aca-3392-404f-aece-c2c8ec67be64", "type": "concept", "title": "prior restraint"}, {"id": "6860a6b8-d333-4d4e-b77f-7a9ec25200da", "type": "concept", "title": "public forums"}, {"id": "87c46418-dad4-4f04-9919-c644da083b3d", "type": "concept", "title": "press rights"}], "description": "Students learn the constitutional and democratic foundations of free expression and a free press."}, {"id": "b3a500f7-d7dd-4d4f-9236-a5053e4ac4ab", "type": "subtopic", "title": "Libel, privacy, and intellectual property", "children": [{"id": "eb1bc9a3-5d16-4db8-8e3a-286fc845f0a8", "type": "concept", "title": "defamation"}, {"id": "c0054e66-d69d-4db9-a0c9-984a868c998f", "type": "concept", "title": "false light and intrusion"}, {"id": "b83e582c-f76c-4b93-be2a-8b143e5b523d", "type": "concept", "title": "copyright and fair use"}], "description": "The course introduces the legal risks that communicators must recognize before publication."}, {"id": "7b0fd959-5b7f-4ddb-bd44-b4c7e7c345e9", "type": "subtopic", "title": "Journalism ethics", "children": [{"id": "8b6c3f09-2261-46de-9dcc-6ec51ac86326", "type": "concept", "title": "SPJ principles"}, {"id": "6aef4cf3-4cbc-4356-9b81-11d649cede7f", "type": "concept", "title": "corrections"}, {"id": "1deb81f7-b03f-4f2d-a861-3015ae83a389", "type": "concept", "title": "conflicts and gifts"}], "description": "Students study verification, independence, accountability, transparency, minimizing harm, and conflicts of interest."}, {"id": "671459d8-edd7-4582-984a-24388a28e82f", "type": "subtopic", "title": "Global press freedom and safety", "children": [{"id": "90fa0032-7cea-4780-896b-2fb2ecdfb45e", "type": "concept", "title": "censorship"}, {"id": "7a4b0e7c-3eab-403f-a08d-6c495206467f", "type": "concept", "title": "source confidentiality"}, {"id": "b87263e1-dc2b-4719-b629-9801795ec91f", "type": "concept", "title": "digital safety"}], "description": "The unit examines censorship, harassment, surveillance, source protection, and journalist safety."}]}, {"id": "2e00aa1e-0756-41ba-a04d-5296456780ff", "type": "topic", "title": "Representation, Diversity, and Global Media Systems", "description": "Students learn to analyze whose voices are amplified, whose are excluded, and how media systems differ across cultures, nations, and communities.", "children": [{"id": "bac705b0-8116-4119-9baa-4c2b51fb7a55", "type": "subtopic", "title": "Representation and stereotyping", "children": [{"id": "399f3ced-850e-46bd-aa6b-b8122c007520", "type": "concept", "title": "symbolic annihilation"}, {"id": "ca5dc654-2065-494d-b133-3d58a8ef537b", "type": "concept", "title": "stereotypes"}, {"id": "00ba4168-fac3-44e2-956d-04dc14cbc30f", "type": "concept", "title": "intersectionality"}], "description": "Students examine how race, gender, class, disability, religion, sexuality, and nationality appear in media narratives."}, {"id": "c438ef13-09c0-4c78-b890-f7e73ff0cffe", "type": "subtopic", "title": "Newsroom diversity and source diversity", "children": [{"id": "37fa1c9a-e9b9-4078-ad20-0703f9c07d6e", "type": "concept", "title": "source audits"}, {"id": "2040d745-493b-4eb8-86a3-aac0220d322c", "type": "concept", "title": "community listening"}, {"id": "6f77e4e3-0c2b-4d74-814c-c39376cebfb6", "type": "concept", "title": "inclusive editing"}], "description": "The course connects inclusive journalism to accuracy, trust, community knowledge, and editorial blind spots."}, {"id": "434b0803-549c-456f-9204-711e06764343", "type": "subtopic", "title": "Global media systems", "children": [{"id": "85a1855d-96f3-4138-9119-ba08a6d07a07", "type": "concept", "title": "public service broadcasting"}, {"id": "e40f83d9-72ed-48d0-8296-34763393f2df", "type": "concept", "title": "state media"}, {"id": "0d70d1b6-8f09-41d7-bb5b-2436c5651943", "type": "concept", "title": "transnational media"}], "description": "Students compare commercial, public-service, state-controlled, and hybrid media systems."}, {"id": "bcfb1540-5a3e-4504-bd13-9e81ffe915f4", "type": "subtopic", "title": "Media, power, and social change", "children": [{"id": "22ca8028-6a21-4c15-a29e-dc606985dbf8", "type": "concept", "title": "activist media"}, {"id": "a55b4520-08aa-4b47-831b-7f6ab4d94f3d", "type": "concept", "title": "networked movements"}, {"id": "90ab32b8-da3a-479d-8c26-88253c743444", "type": "concept", "title": "media and democracy"}], "description": "Students study media roles in protest, social movements, democracy, authoritarianism, and cultural change."}]}, {"id": "1a89c2a8-83dc-4437-b12d-2009d9c10373", "type": "topic", "title": "Misinformation, Verification, and Media Literacy", "description": "This unit provides the habits needed to navigate polluted information environments with skepticism and care.", "children": [{"id": "77cb6024-7337-4c89-8660-071a25b46d8f", "type": "subtopic", "title": "Information disorder", "children": [{"id": "91385ca7-b914-4dcb-a203-585e53525680", "type": "concept", "title": "false context"}, {"id": "aef285a3-0c90-43f5-a220-f72d5651c20d", "type": "concept", "title": "manipulated content"}, {"id": "cae6d19a-5548-4fe6-b284-1fa471dc61f0", "type": "concept", "title": "coordinated campaigns"}], "description": "Students distinguish misinformation, disinformation, malinformation, propaganda, rumor, satire, and error."}, {"id": "192c02ae-b9eb-4e52-ab4d-6f4810feb253", "type": "subtopic", "title": "Verification basics", "children": [{"id": "8035c596-2b83-4869-8c1c-cecb95bb461c", "type": "concept", "title": "lateral reading"}, {"id": "ea1bd8e0-89bc-4705-bda9-89ec1f937702", "type": "concept", "title": "reverse image search"}, {"id": "e7dd2f73-39b4-421a-bf75-2c6b8e405354", "type": "concept", "title": "source provenance"}], "description": "The course introduces lateral reading, source tracing, image search, geolocation clues, and claims checking."}, {"id": "134b1002-0e69-49a9-9281-05f7e6249f26", "type": "subtopic", "title": "Trust and credibility", "children": [{"id": "c008ea06-e8